"use client";

import { useState, type FormEvent } from "react";
import { cadastrar } from "./api";
import { MensagemErro } from "./mensagem-erro";

export function FormularioAvaliacao({ emailAvaliador, onSaved }: {
  emailAvaliador?: string;
  onSaved: () => void;
}) {
  const [enviando, setEnviando] = useState(false);
  const [salvo, setSalvo] = useState(false);
  const [erro, setErro] = useState<Error | null>(null);

  async function salvar(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const form = event.currentTarget;
    const entrada = new FormData(form);
    setSalvo(false);
    setErro(null);
    setEnviando(true);

    try {
      await cadastrar({
        emailAvaliado: String(entrada.get("emailAvaliado")).trim(),
        comentarios: String(entrada.get("comentarios")).trim(),
        nota: Number(entrada.get("nota")),
      });
      form.reset();
      setSalvo(true);
      onSaved();
    } catch (error) {
      setErro(error instanceof Error ? error : new Error("Não foi possível salvar a avaliação."));
    } finally {
      setEnviando(false);
    }
  }

  return (
    <section className="panel" aria-labelledby="nova-avaliacao">
      <div className="panel-heading"><h2 id="nova-avaliacao">Nova avaliação</h2></div>
      <form onSubmit={salvar} className="panel-body">
        {!emailAvaliador && <p className="feedback error">Verifique seu e-mail no Auth0 e entre novamente para cadastrar.</p>}
        <fieldset disabled={enviando || !emailAvaliador}>
          <label>
            E-mail do avaliador
            <input value={emailAvaliador ?? ""} type="email" readOnly />
          </label>
          <label>
            E-mail do avaliado
            <input name="emailAvaliado" type="email" placeholder="pessoa@empresa.com" required maxLength={254} />
          </label>
          <label>
            Nota de 0 a 10
            <input name="nota" type="number" min={0} max={10} step={1} placeholder="0–10" required />
          </label>
          <label>
            Comentários
            <textarea name="comentarios" placeholder="Escreva sua avaliação" maxLength={2000} required rows={4} />
          </label>
          <button className="button primary" type="submit">{enviando ? "Salvando…" : "Cadastrar avaliação"}</button>
        </fieldset>
        {erro && <MensagemErro erro={erro} />}
        {salvo && <p className="feedback success" role="status">Avaliação cadastrada.</p>}
      </form>
    </section>
  );
}
